// Generated by Trae Work
(function() {
  var style = getComputedStyle(document.documentElement);
  var accent = style.getPropertyValue('--accent').trim();
  var accent2 = style.getPropertyValue('--accent2').trim();
  var ink = style.getPropertyValue('--ink').trim();
  var muted = style.getPropertyValue('--muted').trim();
  var rule = style.getPropertyValue('--rule').trim();
  var bg2 = style.getPropertyValue('--bg2').trim();

  var cats = ['锁具','门把手','窗户限位器','窗户把手','门合页','窗户配件','门用闭门器','门扣，门栓','门锁舌','插销，闸阀'];
  var rev = [65138488,47104789,36078243,22167537,15524008,13946277,8830979,6552821,6366330,5450341]; // RUB
  var sales = [198342,84913,270524,77046,53826,50772,13069,32584,33099,34876];
  var priceRub = [328,555,133,288,288,275,676,201,192,156];
  var skuCount = [222,149,132,63,74,58,22,40,50,51];
  var brands = [50,29,22,20,19,22,7,10,21,16];
  var sellers = [97,47,56,32,36,35,10,21,36,27];

  var RATE = 0.0774; // 1 RUB = 0.0774 CNY
  var revW = rev.map(function(v){ return v*RATE/10000; });       // 万元
  var priceCny = priceRub.map(function(v){ return Math.round(v*RATE); }); // 元

  function wan(v){ return (v/10000).toFixed(1)+'万'; }
  function num(v){ return v.toLocaleString(); }

  // Chart: revenue share (pie-donut)
  var chShare = echarts.init(document.getElementById('chart-share'), null, {renderer:'svg'});
  chShare.setOption({
    animation:false,
    color:['#2f5d8a','#3a6f9e','#4b8cb8','#b48a3f','#c8a35c','#8aa2b8','#5f7a92','#a9b8c6','#cdb98a','#879ab0'],
    tooltip:{trigger:'item',appendToBody:true,valueFormatter:function(v){return wan(v*RATE)+' 元';}},
    legend:{bottom:0,type:'scroll',textStyle:{color:muted},itemWidth:12,itemHeight:12},
    series:[{
      type:'pie',radius:['38%','68%'],center:['50%','44%'],
      itemStyle:{borderColor:bg2,borderWidth:1.5},
      label:{color:ink,fontSize:11,formatter:'{b}\n{d}%'},
      data:cats.map(function(c,i){return {name:c,value:rev[i]};})
    }]
  });
  window.addEventListener('resize', function(){ chShare.resize(); });

  // Chart: revenue bar (万元)
  var chRev = echarts.init(document.getElementById('chart-rev'), null, {renderer:'svg'});
  chRev.setOption({
    animation:false,
    grid:{left:8,right:16,top:10,bottom:6,containLabel:true},
    tooltip:{trigger:'axis',appendToBody:true,axisPointer:{type:'shadow'},valueFormatter:function(v){return v.toFixed(1)+'万 元';}},
    xAxis:{type:'value',axisLabel:{color:muted,fontSize:11,formatter:function(v){return v+'万';}},splitLine:{lineStyle:{color:rule}}},
    yAxis:{type:'category',data:cats.slice().reverse(),axisLine:{show:false},axisTick:{show:false},axisLabel:{color:ink,fontSize:12}},
    series:[{type:'bar',data:[].concat(revW).reverse(),barWidth:18,
      itemStyle:{color:accent,borderRadius:[0,4,4,0]},
      label:{show:true,position:'right',color:muted,fontSize:11,formatter:function(p){return p.value.toFixed(0)+'万';}} }]
  });
  window.addEventListener('resize', function(){ chRev.resize(); });

  // Chart: sales bar
  var chSales = echarts.init(document.getElementById('chart-sales'), null, {renderer:'svg'});
  chSales.setOption({
    animation:false,
    grid:{left:8,right:20,top:10,bottom:6,containLabel:true},
    tooltip:{trigger:'axis',appendToBody:true,axisPointer:{type:'shadow'},valueFormatter:function(v){return num(v)+' 件';}},
    xAxis:{type:'value',axisLabel:{color:muted,fontSize:11,formatter:function(v){return v>=1000?(v/1000)+'K':v;}},splitLine:{lineStyle:{color:rule}}},
    yAxis:{type:'category',data:[].concat(cats).reverse(),axisLine:{show:false},axisTick:{show:false},axisLabel:{color:ink,fontSize:12}},
    series:[{type:'bar',data:[].concat(sales).reverse(),barWidth:18,
      itemStyle:{color:accent2,borderRadius:[0,4,4,0]},
      label:{show:true,position:'right',color:muted,fontSize:11,formatter:function(p){return p.value>=1000?Math.round(p.value/1000)+'K':p.value;}} }]
  });
  window.addEventListener('resize', function(){ chSales.resize(); });

  // Chart: bubble (sales, avg price in CNY)
  var chBubble = echarts.init(document.getElementById('chart-bubble'), null, {renderer:'svg'});
  chBubble.setOption({
    animation:false,
    grid:{left:8,right:16,top:10,bottom:10,containLabel:true},
    tooltip:{trigger:'item',appendToBody:true,
      formatter:function(p){
        var d=p.data;
        return d.name+'<br/>销量：'+num(d.value[0])+' 件<br/>均价：'+d.value[1]+' 元（'+d.value[3]+' ₽）';
      }},
    xAxis:{name:'销量(件)',type:'log',axisLabel:{color:muted,fontSize:11},splitLine:{lineStyle:{color:rule}},nameTextStyle:{color:muted}},
    yAxis:{name:'均价(元)',type:'value',axisLabel:{color:muted,fontSize:11},splitLine:{lineStyle:{color:rule}},nameTextStyle:{color:muted}},
    series:[{type:'scatter',data:cats.map(function(c,i){return {name:c,value:[sales[i],priceCny[i],skuCount[i],priceRub[i]]};}),
      symbolSize:function(v){return Math.max(10,Math.sqrt(v[2])*2.2);},
      itemStyle:{color:function(p){
        var idx=cats.indexOf(p.data.name);
        return idx<2?accent:accent2;
      },opacity:0.75},
      label:{show:true,formatter:function(p){return p.data.name;},position:'top',color:ink,fontSize:11}
    }]
  });
  window.addEventListener('resize', function(){ chBubble.resize(); });

  // Chart: concentration
  var chDiff = echarts.init(document.getElementById('chart-diffuse'), null, {renderer:'svg'});
  var brandDensity = brands.map(function(b,i){ return b/skuCount[i]; });
  var sellerDensity = sellers.map(function(s,i){ return s/skuCount[i]; });
  chDiff.setOption({
    animation:false,
    color:[accent,accent2],
    legend:{bottom:0,textStyle:{color:muted}},
    grid:{left:8,right:16,top:10,bottom:8,containLabel:true},
    tooltip:{trigger:'axis',appendToBody:true,axisPointer:{type:'shadow'},
      formatter:function(ps){
        var i=cats.indexOf(ps[0].axisValue);
        var s=[];
        s.push(cats[i]);
        s.push('品牌密度：'+ps[0].value.toFixed(2)+' 品牌/SKU');
        s.push('卖家密度：'+ps[1].value.toFixed(2)+' 卖家/SKU');
        s.push('SKU数：'+skuCount[i]+'，品牌：'+brands[i]+'，卖家：'+sellers[i]);
        return s.join('<br/>');
      }},
    xAxis:{type:'category',data:cats,axisLabel:{color:ink,fontSize:11,interval:0,rotate:28},axisLine:{lineStyle:{color:rule}},axisTick:{show:false}},
    yAxis:{type:'value',name:'密度(数/SKU)',axisLabel:{color:muted,fontSize:11},splitLine:{lineStyle:{color:rule}},nameTextStyle:{color:muted}},
    series:[
      {name:'品牌密度',type:'bar',data:brandDensity,barWidth:10,itemStyle:{borderRadius:[3,3,0,0]}},
      {name:'卖家密度',type:'bar',data:sellerDensity,barWidth:10,itemStyle:{borderRadius:[3,3,0,0]}}
    ]
  });
  window.addEventListener('resize', function(){ chDiff.resize(); });
})();